#include "shanten_core.hpp"
#include <random>
#include <iostream>
#include <vector>
#include <array>
#include <algorithm>
using namespace std;
int ov(const array<int,9>&a,const array<int,9>&t){int z=0;for(int i=0;i<9;i++)z+=min(a[i],t[i]);return z;}
int main(int argc,char**argv){int reps=argc>1?atoi(argv[1]):200000;mt19937_64 rng(0x5eeda11);Solver s(9,true),h(7,false);vector<int>wall;for(int i=0;i<34;i++)for(int j=0;j<4;j++)wall.push_back(i);for(int N=14;N<=37;N++){array<unsigned long long,8>hist{};for(int rep=0;rep<reps;rep++){shuffle(wall.begin(),wall.end(),rng);array<int,34>c{};for(int i=0;i<N;i++)c[wall[i]]++;uint64_t m=sig_bit(0,0,0);for(int g=0;g<4;g++){array<uint8_t,9>a{};int len=g==3?7:9;for(int i=0;i<len;i++)a[i]=c[g*9+i];m=combine_mask(m,g==3?h.rec(a):s.rec(a));}int v=99;for(int M=0;M<=4;M++)for(int t=0;t<=4;t++)for(int p=0;p<=1;p++)if(m&sig_bit(M,t,p))v=min(v,8-2*M-min(t,4-M)-p);int q=0,u=0;bool kp=0;for(int i=0;i<34;i++){q+=c[i]/2;bool term=i>=27||i%9==0||i%9==8;u+=term&&c[i]>0;kp|=term&&c[i]>=2;}v=min(v,6-min(q,7));v=min(v,13-u-(kp?1:0));int bb=0;for(int a=0;a<3;a++)for(int b=0;b<3;b++)if(b!=a)for(int d=0;d<3;d++)if(d!=a&&d!=b){int z=0;for(int su=0;su<3;su++){int sk=su==0?a:su==1?b:d;for(int k=0;k<3;k++)z+=c[su*9+sk+3*k]>0;}bb=max(bb,z);}int hn=0;for(int i=27;i<34;i++)hn+=c[i]>0;v=min(v,13-min(14,bb+hn));
 // combination dragon
 array<array<int,3>,3> base{}; array<array<int,3>,3> ext{}; for(int su=0;su<3;su++){array<int,9>a{};for(int j=0;j<9;j++)a[j]=c[su*9+j];for(int g=0;g<3;g++){array<int,9>sk{};sk[g]=sk[g+3]=sk[g+6]=1;base[su][g]=ov(a,sk);ext[su][g]=base[su][g];for(int st=0;st<7;st++){array<int,9>mel{};mel[st]++;mel[st+1]++;mel[st+2]++;for(int p=0;p<9;p++){array<int,9>tar=sk;tar[st]++;tar[st+1]++;tar[st+2]++;tar[p]+=2;bool ok=1;for(int z:tar)ok&=z<=4;if(ok)ext[su][g]=max(ext[su][g],ov(a,tar));} }for(int x=0;x<9;x++)for(int p=0;p<9;p++){array<int,9>tar=sk;tar[x]=3;tar[p]+=2;bool ok=1;for(int z:tar)ok&=z<=4;if(ok)ext[su][g]=max(ext[su][g],ov(a,tar));}}}
 int he=0;for(int x=0;x<7;x++)for(int p=0;p<7;p++){int z=0;z+=min(c[27+x],3);z+=min(c[27+p],2);if(x==p)z=min(c[27+x],5);if(x!=p)he=max(he,z);}int lb=0;for(int a=0;a<3;a++)for(int b=0;b<3;b++)if(b!=a)for(int d=0;d<3;d++)if(d!=a&&d!=b){int basev=base[0][a]+base[1][b]+base[2][d];int delta=max({he,ext[0][a]-base[0][a],ext[1][b]-base[1][b],ext[2][d]-base[2][d]});lb=max(lb,basev+delta);}v=min(v,13-lb);hist[max(-1,min(6,v))+1]++;}cout<<N;for(auto x:hist)cout<<" "<<x;cout<<"\n";}}
